/**
 * The tech's bio (v2.5587, punch list #114; the plan `to-dos/tech-about-lines/README.md`). The office writes a few
 * lines about each tech in the company's words, like the resume handed over with a plumber; joined in order they are
 * the bio a customer gets as a second text the first time the tech presses On my way to them. Pure: the lines from
 * their rows, the tech's usual picks, the opener, the bio's words for a pick and a language, the count against the
 * cap, whether a thread already carried a tech's bio, and the words the desk, the Settings block and the sheet read.
 * The reads and writes are `bioIo.ts`; the server composes the text with the same rules (`quo-send`'s tech path,
 * PR 3) so what the tech read is what goes. No import a copy for the edge cannot hold.
 */
import type { PortalLang } from '../gc/portalI18n.ts'

/** The most characters the whole bio holds in one language, opener included: two text segments. */
export const BIO_CAP = 320

/** A `user_bio_lines` row as the client reads it. */
export interface BioLineRow {
  id: string
  user_id?: string
  text: string
  text_es: string | null
  position: number
  added_at?: string | null
  removed_at: string | null
  off_by_user_at: string | null
}

/** One line of a tech's bio. */
export interface BioLine {
  id: string
  text: string
  textEs: string | null
  position: number
  addedAt: number
  removed: boolean
  /** The tech turned it off in Settings: out of their usual picks. */
  offByUser: boolean
}

const atOf = (iso: string | null | undefined) => Date.parse(iso ?? '') || 0

/** The rows as lines, in the office's order: place, then when added, then id. */
export function bioLinesFromRows(rows: readonly BioLineRow[]): BioLine[] {
  return rows
    .map((r) => ({
      id: r.id,
      text: r.text,
      textEs: r.text_es?.trim() ? r.text_es : null,
      position: r.position,
      addedAt: atOf(r.added_at),
      removed: r.removed_at != null,
      offByUser: r.off_by_user_at != null,
    }))
    .sort((a, b) => a.position - b.position || a.addedAt - b.addedAt || a.id.localeCompare(b.id))
}

/** The lines that are still there, in order. */
export function liveLines(lines: readonly BioLine[]): BioLine[] {
  return lines.filter((l) => !l.removed)
}

/** The tech's usual picks: every live line they have not turned off. The window on the sheet opens with these ticked. */
export function usualPicks(lines: readonly BioLine[]): string[] {
  return liveLines(lines)
    .filter((l) => !l.offByUser)
    .map((l) => l.id)
}

/** The first word of a name: "Luis" from "Luis Ortega". Null for nothing. */
export function firstNameOf(name: string | null | undefined): string | null {
  return name?.trim().split(/\s+/)[0] || null
}

/** The words the bio opens with: "A little about Luis:" / "Un poco sobre Luis:". The same rule as `bio_opener` in SQL. */
export function bioOpener(first: string | null, lang: PortalLang = 'en'): string {
  return `${lang === 'es' ? 'Un poco sobre' : 'A little about'} ${first ?? 'me'}:`
}

/** A line's words in a language, or null when the language has none. */
function wordsIn(line: BioLine, lang: PortalLang): string | null {
  return lang === 'es' ? line.textEs : line.text
}

export interface BioTextInput {
  lines: readonly BioLine[]
  /** The lines that go, by id; null takes the tech's usual picks. A removed id is ignored. */
  picked?: readonly string[] | null
  /** The tech's first name. */
  first: string | null
  /** The customer's language: Spanish takes only the lines that have it. */
  lang?: PortalLang
}

/** The lines that go for a pick and a language, in order. */
export function bioPickedLines({ lines, picked, lang = 'en' }: BioTextInput): BioLine[] {
  const ids = new Set(picked ?? usualPicks(lines))
  return liveLines(lines).filter((l) => ids.has(l.id) && wordsIn(l, lang)?.trim())
}

/**
 * The bio as the customer gets it: the opener, then the picked lines joined by a space. Null when nothing goes — no
 * line, every line turned off, or a Spanish reader with no Spanish line — so no bio is sent rather than an empty one.
 */
export function bioText(input: BioTextInput): string | null {
  const lang = input.lang ?? 'en'
  const lines = bioPickedLines(input)
  if (lines.length === 0) return null
  return `${bioOpener(input.first, lang)} ${lines.map((l) => wordsIn(l, lang)!.trim()).join(' ')}`
}

/**
 * The office's count: the whole bio with every live line, whichever the tech turned off, since they may turn it back
 * on. One number a language; the Spanish counts only the lines that have Spanish. Zero with no line.
 */
export function bioLength(lines: readonly BioLine[], first: string | null, lang: PortalLang = 'en'): number {
  const live = liveLines(lines).filter((l) => wordsIn(l, lang)?.trim())
  if (live.length === 0) return 0
  return `${bioOpener(first, lang)} ${live.map((l) => wordsIn(l, lang)!.trim()).join(' ')}`.length
}

/**
 * The length the whole would have with one line's new words, in each language: the desk refuses an add or an edit
 * past the cap before the server does. `editingId` null means a new line at the end.
 */
export function bioLengthWith(lines: readonly BioLine[], first: string | null, editingId: string | null, text: string, textEs: string | null): { en: number; es: number } {
  const own: BioLine = { id: editingId ?? '__new__', text: text.trim(), textEs: textEs?.trim() || null, position: Number.MAX_SAFE_INTEGER, addedAt: 0, removed: false, offByUser: false }
  const next = editingId ? lines.map((l) => (l.id === editingId ? { ...own, position: l.position, addedAt: l.addedAt } : l)) : [...lines, own]
  return { en: bioLength(next, first, 'en'), es: bioLength(next, first, 'es') }
}

/** The count as the desk says it: "129 left of 320", or "12 over 320". */
export function leftWords(length: number): string {
  const left = BIO_CAP - length
  return left >= 0 ? `${left} left of ${BIO_CAP}` : `${-left} over ${BIO_CAP}`
}

/** A line in the customer's thread as the sheet reads it for the memory. */
export interface IntroducedTail {
  direction: string
  introducesUserId: string | null
}

/** True when a line in this customer's thread already carried this tech's bio. */
export function introduced(tail: readonly IntroducedTail[], userId: string): boolean {
  return tail.some((m) => m.direction === 'out' && m.introducesUserId === userId)
}

